import{c as l,U as e,j as a,m as t}from"./chunks/framework.DQFmIr4R.js";const f=JSON.parse('{"title":"变更记录","description":"","frontmatter":{},"headers":[],"relativePath":"zh/changelog.md","filePath":"zh/changelog.md","lastUpdated":1782214112000}'),o={name:"zh/changelog.md"};function c(n,i,s,d,r,_){return e(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="变更记录" tabindex="-1">变更记录 <a class="header-anchor" href="#变更记录" aria-label="Permalink to “变更记录”">​</a></h1><h2 id="v1-—-初始定义" tabindex="-1">v1 — 初始定义 <a class="header-anchor" href="#v1-—-初始定义" aria-label="Permalink to “v1 — 初始定义”">​</a></h2><ul><li>载荷格式统一为路径条目模式，移除目录树/扁平双模式</li><li>A区/B区完全分离：A区存文件元数据+内容，B区存 Manifest+自定义数据</li><li>配置字节 0 位域重新设计： <ul><li>b0-b1: 压缩算法（00=LZMA, 01=Brotli, 10=Deflate）</li><li>b2-b3: LZMA 字典大小（00=32M, 01=64M, 10=128M, 11=256M）</li><li>b4: HasCustom（B区自定义数据段）</li><li>b5: HasManifest（B区 Manifest）</li><li>b6: Encrypted（A区 AES-256 加密）</li></ul></li><li>文件数量字段固定为 uint32</li><li>文件内容长度字段固定为 uint64，移除 ZIP64 式扩展</li><li>A区长度字段（uint32）始终存在，用于分隔 A区和 B区</li><li>Manifest 改为可选（HasManifest 位控制），仅用于应用元数据</li><li>新增 AES-256-GCM 加密支持（密码派生：PBKDF2-SHA256, 100000 次迭代）</li><li>路径分隔符强制使用 <code>/</code>，解包时自动转换为系统分隔符</li><li>LZMA 字典大小支持 32/64/128/256 MiB，默认 64 MiB</li><li>库与 CLI 分离：<code>src/</code> 为纯库，<code>cli/</code> 为命令行入口</li><li>JavaScript 库支持浏览器和 Node.js 双环境</li><li>魔数 <code>TTP\\x01</code>，固定 26 字节头部</li><li>三种载荷模式：目录树、扁平标准、扁平扩展</li><li>三种压缩算法：LZMA、Brotli、Deflate</li><li>S-Box 固定置换混淆（种子 <code>0x5A7B3C9D</code>）</li><li>分卷支持（<code>.ttp.001</code>, <code>.ttp.002</code>, …）</li><li>自定义数据段（可选，HasCustom 标志位）</li><li>Manifest 透传</li></ul>',3)])])}const M=l(o,[["render",c]]);export{f as __pageData,M as default};
